import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        print(-1)
        return

    n = int(data[0])

    if n == 0:
        print(-1)
        return

    if len(data) < n + 1:
        print(-1)
        return

    nums = list(map(int, data[1:n+1]))

    if n == 1:
        print(-1)
        return

    min_val = min(nums)
    count_min = nums.count(min_val)

    if count_min < n:
        second_min = min(x for x in nums if x != min_val)
        print(second_min)
    else:
        print(-1)

if __name__ == "__main__":
    main()
